function teamRereviewHistory(v){return `<section><h3>Earlier mentor feedback (historical)</h3><p>Review v${v.priorReview.version} · Now assessing submission v${v.submission.version}</p><p>${esc(v.priorReview.feedback)}</p><dl>${v.task.domains.map(k=>`<dt>${esc(typeof taskDomainNames!=='undefined'?taskDomainNames[k]||k:k)}</dt><dd>${v.priorReview.scores[k]===null?'Not assessed':esc(v.priorReview.scores[k])+' / 4'} · Historical / not verified complete</dd>`).join('')}</dl><h3>Student's explanation of the revision</h3><p>${esc(v.submission.revisionReason)}</p></section>`}
